namespace HaelpMi.Core.Models;

/// <summary>
/// Fixed at build time by the Install-Creator, shipped as a small JSON file inside the
/// installer payload (see Install-Creator/DeploymentWriter) and copied to
/// <c>{app}\deployment.json</c> next to the executables. Read once at startup - never
/// user-editable, never regenerated by the running app itself.
///
/// <see cref="CustomerGroupId"/> is what lets two independent HälpMi installations
/// coexist on the same physical network without ever seeing each other (Pflichtenheft
/// Teil 2, Abschnitt 6): every network packet carries it, and a receiver silently drops
/// anything with a different value.
/// </summary>
public sealed class DeploymentInfo
{
    public required Guid CustomerGroupId { get; set; }

    public required Role Role { get; set; }

    /// <summary>
    /// True for installers built with the Install-Creator's "Test-Installer" checkbox
    /// (installer password optional, no customer name required). Never true for a real
    /// deployment - purely a build-time flag carried through so the running app can, if
    /// useful later, show a "Test-Build" marker; nothing in Phase-2 scope currently
    /// branches on it at runtime beyond that.
    /// </summary>
    public bool IsTestInstaller { get; set; }

    /// <summary>
    /// Multi-VLAN-Bootstrap-Seed, optional im Install-Creator vorbelegt (Nutzerwunsch
    /// 13.08.2026) - IP/Hostname eines Geräts in einem anderen, nur gerouteten Subnetz/VLAN,
    /// das dieses Gerät beim Discovery-Boot-Call zusätzlich zum lokalen Broadcast unicastet
    /// (siehe <see cref="DiscoveryService"/>). Reiner Fallback für den allerersten Start,
    /// solange <see cref="SharedConfig.BridgeSeedAddresses"/> noch leer ist (frisch
    /// installiertes Gerät hat noch nie einen Config-Sync erhalten) - danach gewinnt der
    /// Admin-Dashboard-Wert, weil der sich hot-reload aktualisieren lässt, ohne einen neuen
    /// Installer bauen zu müssen (IP kann sich per DHCP ändern). Bewusst weiterhin nur eine
    /// einzelne Adresse (Nutzerwunsch 15.08.2026, im Gegensatz zur admin-editierbaren Liste
    /// zur Laufzeit): der Install-Creator läuft immer auf einer eigenen Dev-Maschine, nie im
    /// künftigen Kundennetz - eine Mehrfach-Erkennung/-Eingabe dort hätte keinen echten
    /// Mehrwert gegenüber einem einzelnen, vom Entwickler bewusst eingetragenen Startwert.
    /// </summary>
    public string? BridgeSeedAddress { get; set; }

    /// <summary>
    /// Viertes kryptografisches Schlüsselpaar (Ed25519, CLAUDE.md "Lizenz &amp; Secrets"
    /// Punkt 4, Nutzerwunsch 15.08.2026) - **pro Kunden-Gruppe**, nicht global: Install-
    /// Creator erzeugt es bei jedem Admin-Installer-Build neu, direkt neben der
    /// <see cref="CustomerGroupId"/>. Der öffentliche Schlüssel steckt in **beiden**
    /// Installer-Varianten (jedes Gerät muss Admin-Behauptungen prüfen können).
    /// </summary>
    public string? AdminRolePublicKeyBase64 { get; set; }

    /// <summary>
    /// Nur im Admin-Installer gesetzt, bleibt <c>null</c> im User-Installer - ein
    /// User-Gerät kann damit selbst nie eine gültige Admin-Behauptung erzeugen. Klartext-
    /// Base64, wie <see cref="CustomerGroupId"/> - siehe Planungsnotiz zur verworfenen
    /// DPAPI-Idee (an die verschlüsselnde Maschine gebunden, funktioniert nicht über
    /// Build-Maschine → Kundenrechner hinweg).
    /// </summary>
    public string? AdminRolePrivateKeyBase64 { get; set; }
}
